const Koa = require('koa');
const Router = require('koa-router');
const bodyParser = require('koa-bodyparser');
const { exec } = require('child_process');
const fs = require('fs');
const path = require('path');

const app = new Koa();
const router = new Router();

router.post('/compile', async (ctx) => {
  const { fileName, fileContent } = ctx.request.body;

  if (!fileName || !fileContent) {
    ctx.status = 400;
    ctx.body = { error: 'fileName and fileContent are required' };
    return;
  }

  const fileExtension = path.extname(fileName);
  const tempFilePath = path.join(__dirname, fileName);

  try {
    fs.writeFileSync(tempFilePath, fileContent);

    let compileCommand;
    if (fileExtension === '.ts') {
      compileCommand = `tsc ${tempFilePath}`;
    } else if (fileExtension === '.cpp') {
      compileCommand = `g++ ${tempFilePath} -o ${tempFilePath}.out`;
    } else {
      ctx.status = 400;
      ctx.body = { error: 'Unsupported file extension' };
      return;
    }

    exec(compileCommand, (error, stdout, stderr) => {
      if (error) {
        ctx.body = {
          hasError: true,
          compilerError: stderr || stdout,
        };
      } else {
        ctx.body = {
          hasError: false,
          compilerError: null,
        };
      }
      fs.unlinkSync(tempFilePath);
      if (fileExtension === '.cpp') {
        fs.unlinkSync(`${tempFilePath}.out`);
      }
    });
  } catch (err) {
    ctx.status = 500;
    ctx.body = { error: 'Internal server error' };
  }
});

app.use(bodyParser());
app.use(router.routes()).use(router.allowedMethods());

app.listen(5000, '0.0.0.0', () => {
  console.log('Server running on http://0.0.0.0:5000');
});
```
